// Generates frontend/app/api/hooks.generated.ts: one typed React hook per
// GET endpoint described in frontend/app/api/types.ts (itself generated by
// `npm run generate:types` from the backend's OpenAPI schema).
//
// Run with: node scripts/generate-api-hooks.mjs
//
// This script only *parses* types.ts syntactically (via the TypeScript
// Compiler API) -- it never type-checks anything. Each generated hook
// references `operations["<id>"][...]` directly in the emitted source, so
// the actual response/query types are resolved by `tsc` when the generated
// file itself is compiled, not by this script.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import ts from "typescript";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const TYPES_PATH = path.join(__dirname, "..", "app", "api", "types.ts");
const OUTPUT_PATH = path.join(__dirname, "..", "app", "api", "hooks.generated.ts");

function findInterface(sourceFile, name) {
  for (const statement of sourceFile.statements) {
    if (ts.isInterfaceDeclaration(statement) && statement.name.text === name) {
      return statement;
    }
  }
  throw new Error(`interface ${name} not found in ${TYPES_PATH}`);
}

/** Find a PropertySignature member by name, matching identifier or string-literal keys. */
function getMember(typeLiteral, name) {
  if (!typeLiteral || !ts.isTypeLiteralNode(typeLiteral)) return undefined;
  return typeLiteral.members.find((m) => {
    if (!ts.isPropertySignature(m) || !m.name) return false;
    if (ts.isIdentifier(m.name) || ts.isStringLiteral(m.name) || ts.isNumericLiteral(m.name)) {
      return m.name.text === name;
    }
    return false;
  });
}

function isNeverType(typeNode) {
  return !!typeNode && typeNode.kind === ts.SyntaxKind.NeverKeyword;
}

/** Extract the operation id string out of an `operations["some_id"]` indexed-access type. */
function operationIdFromIndexedAccess(typeNode) {
  if (!typeNode || !ts.isIndexedAccessTypeNode(typeNode)) return undefined;
  const { objectType, indexType } = typeNode;
  if (!ts.isTypeReferenceNode(objectType) || objectType.typeName.getText() !== "operations") {
    return undefined;
  }
  if (!ts.isLiteralTypeNode(indexType) || !ts.isStringLiteral(indexType.literal)) {
    return undefined;
  }
  return indexType.literal.text;
}

function jsDocSummary(member) {
  const docs = ts.getJSDocCommentsAndTags(member);
  for (const doc of docs) {
    if (ts.isJSDoc(doc) && typeof doc.comment === "string" && doc.comment.trim()) {
      return doc.comment.trim();
    }
  }
  return undefined;
}

function toCamelCase(snake) {
  return snake.replace(/_([a-z0-9])/g, (_, c) => c.toUpperCase());
}

function toPascalCase(text) {
  return text
    .split(/[\s_]+/)
    .filter(Boolean)
    .map((w) => w[0].toUpperCase() + w.slice(1))
    .join("");
}

function hookNameFor(summary, operationId) {
  if (summary) return `use${toPascalCase(summary)}`;
  const base = operationId.split("_api_")[0];
  return `use${toPascalCase(base)}`;
}

function main() {
  const sourceText = readFileSync(TYPES_PATH, "utf-8");
  const sourceFile = ts.createSourceFile(TYPES_PATH, sourceText, ts.ScriptTarget.Latest, true);

  const pathsInterface = findInterface(sourceFile, "paths");
  const operationsInterface = findInterface(sourceFile, "operations");

  const hooks = [];

  for (const pathMember of pathsInterface.members) {
    if (!ts.isPropertySignature(pathMember) || !pathMember.name || !ts.isStringLiteral(pathMember.name)) {
      continue;
    }
    const urlPath = pathMember.name.text;
    if (!urlPath.startsWith("/api/")) continue; // skip the SPA catch-all etc.

    const pathType = pathMember.type;
    if (!pathType || !ts.isTypeLiteralNode(pathType)) continue;

    const getMemberNode = getMember(pathType, "get");
    if (!getMemberNode || isNeverType(getMemberNode.type)) continue; // no GET on this path

    const operationId = operationIdFromIndexedAccess(getMemberNode.type);
    if (!operationId) continue;

    const operationMember = operationsInterface.members.find(
      (m) => ts.isPropertySignature(m) && m.name && m.name.getText(sourceFile).replace(/^"|"$/g, "") === operationId,
    );
    if (!operationMember || !operationMember.type || !ts.isTypeLiteralNode(operationMember.type)) continue;

    const responsesType = getMember(operationMember.type, "responses")?.type;
    const response200 = getMember(responsesType, "200")?.type;
    const jsonContentType = getMember(getMember(response200, "content")?.type, "application/json")?.type;

    // Binary responses (FileResponse/Response with no inferable schema) resolve
    // to bare `unknown` -- skip these, they're consumed directly as URLs.
    if (!jsonContentType || jsonContentType.kind === ts.SyntaxKind.UnknownKeyword) {
      continue;
    }

    // Path/query params live on the *operation*, not the path entry (whose own
    // `parameters` is `never` unless every method on that path shares identical
    // params -- openapi-typescript keeps them per-operation otherwise).
    const parametersType = getMember(operationMember.type, "parameters")?.type;
    const pathParamsType = getMember(parametersType, "path")?.type;
    const pathParamNames = [];
    if (pathParamsType && ts.isTypeLiteralNode(pathParamsType)) {
      for (const p of pathParamsType.members) {
        if (ts.isPropertySignature(p) && p.name && (ts.isIdentifier(p.name) || ts.isStringLiteral(p.name))) {
          pathParamNames.push(p.name.text);
        }
      }
    }

    const queryType = getMember(parametersType, "query")?.type;
    const hasQuery = !!queryType && !isNeverType(queryType);

    const summary = jsDocSummary(getMemberNode);
    const name = hookNameFor(summary, operationId);

    hooks.push({ name, urlPath, operationId, pathParamNames, hasQuery });
  }

  writeFileSync(OUTPUT_PATH, render(hooks), "utf-8");
  console.log(`Generated ${hooks.length} hook(s) -> ${path.relative(process.cwd(), OUTPUT_PATH)}`);
  for (const hook of hooks) console.log(`  - ${hook.name}(${hook.urlPath})`);
}

function render(hooks) {
  const lines = [];
  lines.push("/**");
  lines.push(" * This file was auto-generated by scripts/generate-api-hooks.mjs");
  lines.push(" * from app/api/types.ts. Do not make direct changes to the file --");
  lines.push(" * re-run `npm run generate:api-hooks` instead.");
  lines.push(" */");
  lines.push("");
  lines.push('import { buildQueryString, useApi } from "./useApi";');
  lines.push('import type { operations } from "./types";');
  lines.push("");

  for (const hook of hooks) {
    const responseType = `operations["${hook.operationId}"]["responses"]["200"]["content"]["application/json"]`;
    const args = hook.pathParamNames.map((n) => `${toCamelCase(n)}: string | null`);
    if (hook.hasQuery) {
      args.push(`query?: operations["${hook.operationId}"]["parameters"]["query"]`);
    }

    let urlExpr;
    if (hook.pathParamNames.length === 0) {
      urlExpr = hook.hasQuery ? `\`${hook.urlPath}\${buildQueryString(query)}\`` : `"${hook.urlPath}"`;
    } else {
      const template = hook.urlPath.replace(
        /\{([a-zA-Z0-9_]+)\}/g,
        (_, name) => "${" + toCamelCase(name) + "}",
      );
      const guard = hook.pathParamNames.map((n) => `${toCamelCase(n)} !== null`).join(" && ");
      const literalUrl = hook.hasQuery ? `\`${template}\${buildQueryString(query)}\`` : `\`${template}\``;
      lines.push(`export function ${hook.name}(${args.join(", ")}) {`);
      lines.push(`  const url = ${guard} ? ${literalUrl} : null;`);
      lines.push(`  return useApi<${responseType}>(url);`);
      lines.push(`}`);
      lines.push("");
      continue;
    }

    lines.push(`export function ${hook.name}(${args.join(", ")}) {`);
    lines.push(`  return useApi<${responseType}>(${urlExpr});`);
    lines.push(`}`);
    lines.push("");
  }

  return lines.join("\n");
}

main();
